import React, { useEffect, useState } from 'react';

function App() {
  const [seats, setSeats] = useState([]);

  useEffect(() => {
    fetch('/api/seats')
      .then(res => res.json())
      .then(data => setSeats(data));
  }, []);

  return (
    <div>
      <h1>🎬 CineSeat Booking</h1>
      <div className="grid">
        {seats.map(seat => (
          <div key={seat.id}>{seat.id} - {seat.status}</div>
        ))}
      </div>
    </div>
  );
}

export default App;

