import express from 'express';

const app = express();
app.use(express.json());

const seats = [{ id: 1, status: 'available' }];

app.get('/api/seats', (req, res) => {
  res.json(seats);
});

app.post('/api/seats/:id/book', (req, res) => {
  const seat = seats.find(s => s.id === Number(req.params.id));
  if (!seat) return res.status(404).json({ error: 'Not found' });
  if (seat.status === 'booked') return res.status(409).json({ error: 'Already booked' });
  seat.status = 'booked';
  res.json(seat);
});

export default app;

