import request from 'supertest';
import app from '../app.js';
import { describe, test, expect } from 'vitest';

describe('Full-Stack Seat Booking Test Suite', () => {
  test('prevents double booking under concurrent requests', async () => {
    const [res1, res2] = await Promise.all([
      request(app).post('/api/seats/1/book').send({ userId: 'user-A' }),
      request(app).post('/api/seats/1/book').send({ userId: 'user-B' }),
    ]);
    const statuses = [res1.status, res2.status].sort();
    expect(statuses).toEqual([200, 409]);
  });
});
